        }

        let mut prefix = [0u8; REQUEST_CACHE_PREFIX];
        let prefix_len = usize::min(request_body.len(), REQUEST_CACHE_PREFIX);
        prefix[..prefix_len].copy_from_slice(&request_body[..prefix_len]);

        Some(Self {
            len: request_body.len() as u16,
